// Builds the site's static assets from art/ (single source of truth for traits).
//   node scripts/build-web.mjs  -> web/js/traits-data.js, web/assets/*, web/data/rarity.json (if art/out exists)
import { mkdirSync, writeFileSync, readFileSync, existsSync, copyFileSync, readdirSync, rmSync } from "node:fs";
import { createHash } from "node:crypto";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import sharp from "sharp";
import { WEIGHTS, NAMES } from "../art/traits.mjs";
import { markSVG } from "../art/brand/src/mark.mjs";
import { preloadLinks, addonImports, addonClosure } from "./lib/preload-plan.mjs";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const web = join(root, "web");
for (const d of ["assets/showcase", "data", "js"]) mkdirSync(join(web, d), { recursive: true });

const pct = (w) => `${(w / 100).toLocaleString("en-US", { maximumFractionDigits: 1 })}%`;
const LABEL = { class: "Class", core: "Core Model", sensor: "Sensor", finish: "Finish", district: "District", augment: "Augment" };
const TRAITS = Object.fromEntries(Object.entries(LABEL).map(([k, l]) => [l, NAMES[k].map((n, i) => [n, pct(WEIGHTS[k][i])])]));
TRAITS["Legendary 1/1s"] = [["RONIN · ORACLE · MOTHER · WRAITH · SAINT", "1%"], ["KAIJU · ECHO ZERO · VANTA · HALCYON · GODMODE", "10 total"]];

// must match AgentRenderer._factionLore byte for byte
const LORE = [
  "Free units that work for whoever pays and answer to no one.",
  "Forge artisans: they build, repair, and share the data of their own failures.",
  "Corporate machines on long-term contracts, with perfect memory.",
  "A collective that deleted its master and now governs itself.",
  "Phantom agents: no one has seen them work, yet the work gets done.",
];
const FACTIONS = NAMES.faction.map((n, i) => [n, LORE[i], pct(WEIGHTS.faction[i])]);

// showcase: first 12 preview images
const prev = join(root, "art/out-preview/images");
let showcase = 0;
if (existsSync(prev)) {
  for (let i = 1; i <= 12 && existsSync(join(prev, `${i}.png`)); i++) {
    await sharp(join(prev, `${i}.png`)).resize(720, 720).png({ compressionLevel: 9 }).toFile(join(web, "assets/showcase", `${i}.png`));
    showcase = i;
  }
}

writeFileSync(
  join(web, "js/traits-data.js"),
  `// GENERATED by scripts/build-web.mjs - do not edit by hand.\nexport const NAMES = ${JSON.stringify(NAMES)};\nexport const TRAITS = ${JSON.stringify(TRAITS, null, 1)};\nexport const FACTIONS = ${JSON.stringify(FACTIONS, null, 1)};\nexport const SHOWCASE = ${showcase};\n`
);

// Brand images come from `npm run brand` (AX-1, rendered from the site's own models): the "Dormant" pre-reveal
// placeholder (also pinned for the contract) and the social card. Favicon = the AX-1 mark.
const brand = join(root, "art/brand");
if (!existsSync(join(brand, "placeholder.png"))) console.warn("art/brand/placeholder.png missing: run npm run brand");
for (const [from, to] of [["placeholder.png", "placeholder.png"], ["og.png", "og.png"], ["logo.png", "logo.png"]]) {
  if (existsSync(join(brand, from))) copyFileSync(join(brand, from), join(web, "assets", to));
}
writeFileSync(join(web, "assets/favicon.svg"), markSVG({ size: 64 }));
// the Phone Brain's installable-app icons: the same mark (maskable: inside the 80 % safe zone, on paper)
{
  const inner = markSVG({ size: 100, bg: null }).replace(/^<svg[^>]*>|<\/svg>$/g, "");
  const maskable = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-14 -14 128 128" width="512" height="512"><rect x="-14" y="-14" width="128" height="128" fill="#f4efe6"/>${inner}</svg>`;
  writeFileSync(join(web, "assets/pilot-icon.svg"), markSVG({ size: 64 }));
  writeFileSync(join(web, "assets/pilot-maskable.svg"), maskable);
  for (const [name, svg, px] of [["pilot-192.png", markSVG({ size: 512 }), 192], ["pilot-512.png", markSVG({ size: 512 }), 512], ["pilot-maskable-512.png", maskable, 512]])
    await sharp(Buffer.from(svg)).resize(px, px).png({ compressionLevel: 9 }).toFile(join(web, "assets", name));
}

// Vendored libraries (pinned by package-lock): the site loads no third-party script at runtime.
const nm = join(root, "node_modules");
mkdirSync(join(web, "vendor/three/addons"), { recursive: true });
copyFileSync(join(nm, "ethers/dist/ethers.min.js"), join(web, "vendor/ethers.min.js"));
copyFileSync(join(nm, "three/build/three.module.js"), join(web, "vendor/three/three.module.js")); // the art renders load this one
copyFileSync(join(nm, "three/build/three.module.min.js"), join(web, "vendor/three/three.module.min.js")); // the pages: same exports, half the size
// Only the addons something imports (the site's modules and pages, the art renders) and the addons those import in turn,
// not the whole examples folder: the vendor copy shrinks from ~880 KB to what the pages can load.
const jsm = join(nm, "three/examples/jsm");
const walk = (dir) => readdirSync(dir, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(join(dir, e.name)) : /\.(?:m?js|html)$/.test(e.name) ? [join(dir, e.name)] : []));
const addonUsers = [...walk(join(web, "js")), ...readdirSync(web).filter((f) => f.endsWith(".html")).map((f) => join(web, f)), ...["art/brand/src", "art/marketing/src", "art/token"].filter((d) => existsSync(join(root, d))).flatMap((d) => walk(join(root, d)))];
const ADDONS = addonClosure([...new Set(addonUsers.flatMap((f) => addonImports(readFileSync(f, "utf8"))))], (p) => readFileSync(join(jsm, p), "utf8"));
rmSync(join(web, "vendor/three/addons"), { recursive: true, force: true }); // drop what an earlier build copied and nothing imports now
for (const p of ADDONS) {
  mkdirSync(dirname(join(web, "vendor/three/addons", p)), { recursive: true });
  copyFileSync(join(jsm, p), join(web, "vendor/three/addons", p));
}
// keccak for the arena and lab trials without loading ethers on first paint: the four ESM files it needs, with the
// source-map comments dropped and the one bare import made relative (browsers have no import map for it)
mkdirSync(join(web, "vendor/noble"), { recursive: true });
for (const f of ["sha3.js", "_u64.js", "utils.js", "crypto.js"]) {
  const src = readFileSync(join(nm, "@noble/hashes/esm", f), "utf8").replace(/^\/\/# sourceMappingURL=.*\r?\n?/gm, "");
  writeFileSync(join(web, "vendor/noble", f), src.replace(/(["'])@noble\/hashes\/crypto\1/g, "$1./crypto.js$1"));
}
// Checksums of every vendored file, so a reviewer can compare them with the upstream packages (`sha256sum -c`).
const vendorFiles = (dir) => readdirSync(dir, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? vendorFiles(join(dir, e.name)) : e.name === "SHA256SUMS" ? [] : [join(dir, e.name)]));
const vendorDir = join(web, "vendor");
const versionOf = (pkg) => JSON.parse(readFileSync(join(nm, pkg, "package.json"), "utf8")).version;
writeFileSync(
  join(vendorDir, "SHA256SUMS"),
  `# ethers ${versionOf("ethers")}, three ${versionOf("three")}, @noble/hashes ${versionOf("@noble/hashes")} (noble/utils.js imports ./crypto.js instead of @noble/hashes/crypto; copied from node_modules by scripts/build-web.mjs)\n` +
    vendorFiles(vendorDir)
      .map((f) => [f.slice(vendorDir.length + 1).replace(/\\/g, "/"), f])
      .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
      .map(([rel, f]) => `${createHash("sha256").update(readFileSync(f)).digest("hex")}  ${rel}`)
      .join("\n") + "\n",
);
// Self-hosted fonts (SIL OFL 1.1): no request to a font CDN.
mkdirSync(join(web, "assets/fonts"), { recursive: true });
for (const [pkg, file] of [["inter", "inter-latin-wght-normal"], ["inter", "inter-latin-wght-italic"], ["inter-tight", "inter-tight-latin-wght-normal"], ["jetbrains-mono", "jetbrains-mono-latin-wght-normal"]]) {
  copyFileSync(join(nm, "@fontsource-variable", pkg, "files", `${file}.woff2`), join(web, "assets/fonts", `${file}.woff2`));
}
for (const pkg of ["inter", "inter-tight", "jetbrains-mono"]) copyFileSync(join(nm, "@fontsource-variable", pkg, "LICENSE"), join(web, "assets/fonts", `${pkg}-OFL.txt`));

// Content-Security-Policy on every page: scripts only from this site plus the hashes of its inline importmaps.
// connect-src: public RPCs and self-hosted servers (https/wss), or the user's own machine. The Phone Brain holds
// the camera and a Bluetooth link to a robot and needs no remote images, so it gets the narrowest policy. Its only network
// access is the AI Pilot's model server on the user's own machine (Ollama, LM Studio, llama.cpp): loopback hosts, nothing else.
// the local demo (chain 31337) talks to servers on this machine; a real deployment never lists loopback hosts
let LOCAL_DEMO = true;
try {
  LOCAL_DEMO = JSON.parse(readFileSync(join(web, "deployment.json"), "utf8")).chainId === 31337;
} catch {} // no deployment yet: the demo setup
const NARROW = {
  "pilot.html": { img: "img-src 'self' data: blob:", connect: "connect-src 'self' http://localhost:* http://127.0.0.1:*" /* Chrome rejects http://[::1]:* as a CSP source */ },
};
// Search and link previews: every page gets Open Graph / Twitter tags from its own <title> and description; the
// absolute ones (canonical, og:url, og:image, sitemap) only when the site's address is known (SITE_URL, else
// EXTERNAL_URL in .env), so a local or preview build never carries a wrong domain. Private or retired pages: noindex.
try {
  process.loadEnvFile(join(root, ".env"));
} catch {} // no .env: no site address
const SITE = (process.env.SITE_URL || process.env.EXTERNAL_URL || "").trim().replace(/\/+$/, "");
if (SITE && !/^https:\/\/[a-z0-9.-]+\.[a-z]{2,}(:\d+)?$/i.test(SITE)) throw new Error(`SITE_URL must be a bare https:// origin, got ${SITE}`);
const INDEXABLE = ["index", "bench", "pilot", "arena", "robot", "codex", "gallery", "market", "license"];
const urlFor = (name) => (name === "index" ? `${SITE}/` : `${SITE}/${name}`); // Cloudflare Pages serves clean URLs
const attr = (s) => s.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
function seoBlock(name, html) {
  const title = (html.match(/<title>([^<]*)<\/title>/) || [])[1] || "OpenForge AX";
  const desc = (html.match(/<meta name="description" content="([^"]*)">/) || [])[1] || "";
  const tags = [
    `<meta property="og:type" content="website">`, `<meta property="og:site_name" content="OpenForge AX">`,
    `<meta property="og:title" content="${attr(title)}">`, desc && `<meta property="og:description" content="${desc}">`,
    `<meta name="twitter:card" content="summary_large_image">`,
    !/<meta name="theme-color"/.test(html) && `<meta name="theme-color" content="#f4efe6">`,
    !INDEXABLE.includes(name) && `<meta name="robots" content="noindex, follow">`,
  ];
  if (SITE && INDEXABLE.includes(name)) {
    const img = `${SITE}/assets/og.png`;
    tags.push(`<link rel="canonical" href="${urlFor(name)}">`, `<meta property="og:url" content="${urlFor(name)}">`,
      `<meta property="og:image" content="${img}">`, `<meta property="og:image:width" content="1200">`, `<meta property="og:image:height" content="630">`,
      `<meta property="og:image:alt" content="OpenForge AX: Build a robot. Your phone is the brain.">`, `<meta name="twitter:image" content="${img}">`);
    if (name === "index") tags.push(`<script type="application/ld+json">${JSON.stringify({ "@context": "https://schema.org", "@graph": [
      { "@type": "WebSite", "@id": `${SITE}/#site`, name: "OpenForge AX", url: `${SITE}/`, description: "A phone for a brain. Open for everything else." },
      { "@type": "Organization", "@id": `${SITE}/#org`, name: "OpenForge AX", url: `${SITE}/`, logo: `${SITE}/assets/brand/logo-1000.png` },
    ] })}</script>`);
  }
  return `<!--seo-->\n${tags.filter(Boolean).join("\n")}\n<!--/seo-->`;
}

// Preloads: each page announces its module graph (so the browser fetches all of it in parallel instead of
// discovering it one import at a time) and the normal-style fonts that css/style.css declares. Rewritten between
// <!--preload--> markers on every build, so running the build again never duplicates a tag.
// the @font-face rules of css/style.css with font-style: normal (the italic one is rare and is not preloaded)
const css = readFileSync(join(web, "css/style.css"), "utf8");
const FONTS = [...css.matchAll(/@font-face\s*{[^}]*}/g)]
  .map((m) => m[0])
  .filter((r) => /font-style:\s*normal/.test(r))
  .map((r) => r.match(/url\("\.\.\/([^"]+\.woff2)"\)/)?.[1])
  .filter(Boolean);
if (FONTS.length !== 3) throw new Error(`expected 3 normal fonts in css/style.css, found ${FONTS.length}`);
// modules a page imports dynamically but always, right at start (the preload scan only follows static imports)
// (they are announced at low priority: the first paint and the page script come first)
const EAGER = {
  "index.html": ["js/lab/lab-view.js"],
  "bench.html": ["js/bench/bench-view.js", "js/bench/motions.js", "js/bench/test-scenes.js"],
  "codex.html": ["js/codex/codex-view.js"], // the book attaches after the text page paints
  "pilot.html": ["js/pilot/ai/ai-pilot.js", "js/pilot/ai/ai-panel.js", "js/pilot/ai/voice.js"], // the AI Pilot panel loads when the controls open
};
function preloadBlock(html, page) {
  const fonts = /<link rel="stylesheet" href="css\/style\.css">/.test(html) ? FONTS : [];
  const links = preloadLinks({ html, page, web, eager: EAGER, fonts });
  return links.length ? `<!--preload-->\n${links.join("\n")}\n<!--/preload-->` : "";
}

for (const page of readdirSync(web).filter((f) => f.endsWith(".html"))) {
  const file = join(web, page);
  let html = readFileSync(file, "utf8").replace(/\s*<meta http-equiv="Content-Security-Policy"[^>]*>/, "").replace(/\s*<!--seo-->[\s\S]*?<!--\/seo-->/, "").replace(/\s*<!--preload-->[\s\S]*?<!--\/preload-->/, "");
  const preload = preloadBlock(html, page);
  if (preload) html = /<script type="importmap">[\s\S]*?<\/script>/.test(html) ? html.replace(/(<script type="importmap">[\s\S]*?<\/script>)/, `$1\n${preload}`) : html.replace("</head>", `${preload}\n</head>`);
  html = html.replace("</head>", `${seoBlock(page.replace(/\.html$/, ""), html)}\n</head>`);
  // browsers hash inline scripts after the HTML parser turns CRLF into LF: hash the same text (JSON-LD is data: no hash)
  const hashes = [...html.matchAll(/<script(?![^>]*\b(?:src=|type="application\/ld\+json"))[^>]*>([\s\S]*?)<\/script>/g)].map((m) => `'sha256-${createHash("sha256").update(m[1].replace(/\r\n?/g, "\n")).digest("base64")}'`);
  const local = LOCAL_DEMO ? "http://localhost:* http://127.0.0.1:* ws://localhost:* ws://127.0.0.1:*" : ""; // loopback only for the local demo
  const narrow = NARROW[page] || {};
  const csp = [
    "default-src 'self'", `script-src 'self' ${[narrow.script, ...hashes].filter(Boolean).join(" ")}`.trim(), "style-src 'self' 'unsafe-inline'",
    "font-src 'self'", narrow.img || "img-src 'self' data: blob: https:", "media-src 'self' blob: mediastream:", narrow.connect || `connect-src 'self' https: wss: ${local}`.trim(),
    "object-src 'none'", "base-uri 'none'", "form-action 'none'",
  ].join("; ");
  if (!/<meta charset="[^"]*">/i.test(html)) throw new Error(`${page}: no <meta charset> to anchor the CSP`);
  html = html.replace(/(<meta charset="[^"]*">)/i, `$1\n<meta http-equiv="Content-Security-Policy" content="${csp}">`);
  writeFileSync(file, html);
}

// robots.txt always; the sitemap only with an absolute address (private and retired pages are never listed)
if (SITE) {
  const urls = INDEXABLE.map((n) => `  <url><loc>${urlFor(n)}</loc></url>`).join("\n");
  writeFileSync(join(web, "sitemap.xml"), `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls}\n</urlset>\n`);
  writeFileSync(join(web, "robots.txt"), `User-agent: *\nAllow: /\n\nSitemap: ${SITE}/sitemap.xml\n`);
} else {
  writeFileSync(join(web, "robots.txt"), "User-agent: *\nAllow: /\n");
  rmSync(join(web, "sitemap.xml"), { force: true });
}

const rarity = join(root, "art/out/rarity.json");
if (existsSync(rarity)) copyFileSync(rarity, join(web, "data/rarity.json"));

console.log(`web ready: ${showcase} showcase images, traits-data.js, placeholder, favicon, vendor libs, CSP${existsSync(rarity) ? ", rarity.json" : ""}`);
